What changes should be made to the C# code for sentiment analysis to calculate a more precise sentiment score for each review on a scale from -1 to 1 using the given formula: 
sentiment score = (number of positive words - number of negative words) / (number of positive words + number of negative words)
Here is the existing C# code:
public static double CalculateSentiment(string review)
{
    var positiveWords = new List<string>{"good", "great", "excellent"};
    var negativeWords = new List<string>{"bad", "terrible", "awful"};
    var words = review.Split(' ');
    var numPositive = words.Count(w => positiveWords.Contains(w));
    var numNegative = words.Count(w => negativeWords.Contains(w));
    return (double)(numPositive - numNegative) / (double)(numPositive + numNegative);
}
