How can I compare the independence of two countries, USA and Canada, using Java code?
One way to approach this is to use the World Bank API to retrieve data on the "Political Stability and Absence of Violence/Terrorism" indicator for both countries. Here's an example code snippet:
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import org.json.simple.JSONArray;
import org.json.simple.JSONObject;
import org.json.simple.parser.JSONParser;
public class CountryIndependenceComparator {
    public static void main(String[] args) {
        String usaIndicatorCode = "PV.EST";
        String canadaIndicatorCode = "PV.EST";
        String apiUrl = "https://api.worldbank.org/v2/country/USA;CAN/indicator/" + usaIndicatorCode + ";"
                + canadaIndicatorCode + "?format=json";
        try {
            URL url = new URL(apiUrl);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            BufferedReader rd = new BufferedReader(new InputStreamReader(conn.getInputStream()));
            StringBuilder response = new StringBuilder();
            String line;
            while ((line = rd.readLine()) != null) {
                response.append(line);
            }
            rd.close();
            JSONParser parser = new JSONParser();
            JSONArray data = (JSONArray) parser.parse(response.toString());
            for (Object obj : data) {
                JSONObject obj2 = (JSONObject) obj;
                JSONArray dataArr = (JSONArray) obj2.get("data");
                for (Object dataObj : dataArr) {
                    JSONObject dataJson = (JSONObject) dataObj;
                    String countryName = (String) ((JSONObject) dataJson.get("country")).get("value");
                    String indicatorValue = (String) dataJson.get("value");
                    System.out.println("Country: " + countryName + ", Indicator value: " + indicatorValue);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
This code retrieves the Political Stability and Absence of Violence/Terrorism indicator for both USA and Canada, and prints out the results. You can modify this code to retrieve different indicators or compare more countries.

