How can I use C# to generate a chart demonstrating the relationship between air pressure and temperature?
[C# code]
double p0 = 100000; // Standard atmospheric pressure in Pascals
double t0 = 288.15; // Standard temperature in Kelvin
double g = 9.81; // Acceleration due to gravity in m/s^2
double r = 287; // Gas constant for dry air in J/kg K
double cp = 1004; // Specific heat capacity for dry air in J/kg K
double PressureAtAltitude(double h)
{
    return p0 * Math.Pow(1 - (g * h) / (r * t0), g / (cp * r));
}
double TemperatureAtAltitude(double h)
{
    return t0 - (g * h) / cp;
}
// Calculate pressure and temperature at different altitudes
double[] altitudes = { 0, 1000, 2000, 3000, 4000 }; // in meters
double[] pressures = altitudes.Select(h => PressureAtAltitude(h)).ToArray();
double[] temperatures = altitudes.Select(h => TemperatureAtAltitude(h)).ToArray();
// Generate chart
var chart = new System.Windows.Forms.DataVisualization.Charting.Chart();
chart.ChartAreas.Add(new System.Windows.Forms.DataVisualization.Charting.ChartArea());
chart.Series.Add(new System.Windows.Forms.DataVisualization.Charting.Series("Pressure"));
chart.Series.Add(new System.Windows.Forms.DataVisualization.Charting.Series("Temperature"));
chart.Series["Pressure"].ChartType = System.Windows.Forms.DataVisualization.Charting.SeriesChartType.Line;
chart.Series["Temperature"].ChartType = System.Windows.Forms.DataVisualization.Charting.SeriesChartType.Line;
for (int i = 0; i < altitudes.Length; i++)
{
    chart.Series["Pressure"].Points.AddXY(altitudes[i], pressures[i]);
    chart.Series["Temperature"].Points.AddXY(altitudes[i], temperatures[i]);
}
// Display chart
var form = new System.Windows.Forms.Form();
var chartControl = new System.Windows.Forms.DataVisualization.Charting.Chart();
chartControl.Parent = form;
chartControl.Dock = System.Windows.Forms.DockStyle.Fill;
chartControl.Series.Add(new System.Windows.Forms.DataVisualization.Charting.Series("Pressure"));
chartControl.Series.Add(new System.Windows.Forms.DataVisualization.Charting.Series("Temperature"));
chartControl.Series["Pressure"].ChartType = System.Windows.Forms.DataVisualization.Charting.SeriesChartType.Line;
chartControl.Series["Temperature"].ChartType = System.Windows.Forms.DataVisualization.Charting.SeriesChartType.Line;
chartControl.Series["Pressure"].Points.DataBindXY(altitudes, pressures);
chartControl.Series["Temperature"].Points.DataBindXY(altitudes, temperatures);
form.ShowDialog();
