// check connection
if (!$conn) {
    die("Connection failed: " . mysqli_connect_error());
}
// insert user's rating
if (isset($_POST['submit'])) {
    $rating = $_POST['rating'];
    $restaurant = $_POST['restaurant'];
    $query = "INSERT INTO ratings (restaurant, cleanliness) VALUES ('$restaurant', '$rating')";
    mysqli_query($conn, $query);
}
// display current ratings
$query = "SELECT restaurant, AVG(cleanliness) FROM ratings GROUP BY restaurant";
$result = mysqli_query($conn, $query);
// display results in a table format
echo "<table>";
echo "<tr><th>Restaurant</th><th>Cleanliness Rating</th></tr>";
while ($row = mysqli_fetch_assoc($result)) {
    echo "<tr><td>" . $row['restaurant'] . "</td><td>" . round($row['AVG(cleanliness)'], 1) . "/5</td></tr>";
